$codesDir = "scripts/codes"

function Write-Template($id, $title, $desc, $cat, $stars, $author, $views, $updated, $html) {
  $meta = "$id|$title|$desc|$cat|$stars|$author|$views|$updated"
  $b64 = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($html))
  Set-Content -Path "$codesDir/$id.txt" -Value ($meta + "`n" + $b64) -NoNewline
  Write-Host "  $id ($($b64.Length) chars)"
}

Write-Host "Creating templates..."

Write-Template 'stellar-landing' 'Stellar Dev Landing' 'High-conversion SaaS landing page with Intersection Observer scroll animations, live contact form validation, and smooth navigation.' 'Landing Pages' 756 'StellarDev' '21.3k' '3 days ago' @"
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stellar</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:system-ui,sans-serif;scroll-behavior:smooth}body{background:#0f172a;color:#e2e8f0;overflow-x:hidden}nav{position:fixed;top:0;width:100%;background:#0f172a80;backdrop-filter:blur(12px);border-bottom:1px solid #334155;z-index:100}.nav-inner{max-width:1100px;margin:0 auto;display:flex;justify-content:space-between;align-items:center;padding:14px 24px}nav .logo{font-size:1.25rem;font-weight:700;color:#3b82f6}nav ul{display:flex;gap:20px;list-style:none}nav ul a{color:#94a3b8;text-decoration:none;font-size:.875rem}nav ul a:hover{color:#3b82f6}.btn{background:#3b82f6;color:#fff;padding:8px 20px;border-radius:8px;font-size:.875rem;font-weight:600;text-decoration:none;cursor:pointer;border:0;font-family:inherit;display:inline-block}.btn:hover{background:#2563eb}section{padding:100px 24px 60px;max-width:1100px;margin:0 auto}.hero{text-align:center;padding-top:140px;padding-bottom:80px}.hero .badge{display:inline-block;padding:6px 16px;border-radius:99px;font-size:.75rem;font-weight:600;background:#3b82f620;color:#3b82f6;border:1px solid #3b82f630;margin-bottom:20px}.hero h1{font-size:3rem;font-weight:800;max-width:700px;margin:0 auto 16px;line-height:1.15}.hero h1 span{color:#3b82f6}.hero p{font-size:1.05rem;color:#94a3b8;max-width:500px;margin:0 auto 28px;line-height:1.6}.hero .btns{display:flex;gap:12px;justify-content:center}.hero .btns .btn-out{background:0 0;border:1px solid #334155;color:#e2e8f0}.hero .btns .btn-out:hover{background:#1e293b}.features{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:40px}.feature{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:24px;opacity:0;transform:translateY(30px);transition:opacity .6s,transform .6s}.feature.show{opacity:1;transform:translateY(0)}.feature h3{font-size:1rem;margin-bottom:8px}.feature p{font-size:.8rem;color:#94a3b8;line-height:1.5}.contact-form{max-width:500px;margin:40px auto 0}.contact-form input,.contact-form textarea{width:100%;padding:10px 14px;background:#1e293b;border:1px solid #334155;border-radius:8px;color:#e2e8f0;font-size:.9rem;outline:0;margin-bottom:14px;font-family:inherit}.contact-form input:focus,.contact-form textarea:focus{border-color:#3b82f6}.contact-form textarea{height:100px;resize:vertical}.contact-form .error{color:#ef4444;font-size:.75rem;display:none}.contact-form .error.show{display:block}.success-msg{display:none;padding:16px;background:#10b98120;border:1px solid #10b981;border-radius:8px;color:#10b981;text-align:center;margin-top:16px}.success-msg.show{display:block}footer{text-align:center;padding:32px;color:#64748b;font-size:.8rem;border-top:1px solid #334155}@media(max-width:768px){.features{grid-template-columns:1fr}.hero h1{font-size:2rem}}</style></head><body><nav><div class="nav-inner"><span class="logo">Stellar</span><ul><li><a href="#features">Features</a></li><li><a href="#contact">Contact</a></li><li><a href="#" class="btn" onclick="document.getElementById(&#39;contact&#39;).scrollIntoView({behavior:&#39;smooth&#39;})">Get Started</a></li></ul></div></nav><section class="hero"><div class="badge">Now in Public Beta</div><h1>Build Products <span>10x Faster</span></h1><p>The complete platform for modern web developers.</p><div class="btns"><a href="#contact" class="btn">Start Free Trial</a><a href="#features" class="btn btn-out">See Features</a></div></section><section id="features"><h2 style="text-align:center;font-size:1.75rem;margin-bottom:8px">Everything You Need</h2><div class="features" id="featureGrid"><div class="feature"><h3>Instant Deploy</h3><p>Deploy apps globally with one click.</p></div><div class="feature"><h3>Enterprise Auth</h3><p>OAuth, SSO, and RBAC out of the box.</p></div><div class="feature"><h3>Real-time Analytics</h3><p>Live dashboards for performance.</p></div><div class="feature"><h3>Cloud Sync</h3><p>Auto sync across devices.</p></div><div class="feature"><h3>API Integrations</h3><p>200+ third-party services.</p></div><div class="feature"><h3>AI Design</h3><p>Generate UI with natural language.</p></div></div></section><section id="contact"><h2 style="text-align:center;font-size:1.75rem;margin-bottom:8px">Get In Touch</h2><div class="contact-form"><input id="cname" placeholder="Your Name" oninput="clearErr(&#39;name&#39;)"><div class="error" id="err-name">Required</div><input id="cemail" placeholder="Email" type="email" oninput="clearErr(&#39;email&#39;)"><div class="error" id="err-email">Valid email required</div><textarea id="cmsg" placeholder="Message" oninput="clearErr(&#39;msg&#39;)"></textarea><div class="error" id="err-msg">Min 10 chars</div><button class="btn" onclick="submitForm()" style="width:100%">Send</button><div class="success-msg" id="successMsg">Thank you!</div></div></section><footer>&#169; 2026 Stellar</footer><script>var obs=new IntersectionObserver(function(e){e.forEach(function(x){if(x.isIntersecting)x.target.classList.add("show")})},{threshold:.1});document.querySelectorAll(".feature").forEach(function(el,i){el.style.transitionDelay=i*0.1+"s";obs.observe(el)});window.clearErr=function(f){document.getElementById("err-"+f).classList.remove("show");document.getElementById("successMsg").classList.remove("show")};window.submitForm=function(){var v=true;var n=document.getElementById("cname").value.trim();if(!n){document.getElementById("err-name").classList.add("show");v=false}var e=document.getElementById("cemail").value.trim();if(!e||!e.includes("@")){document.getElementById("err-email").classList.add("show");v=false}var m=document.getElementById("cmsg").value.trim();if(m.length<10){document.getElementById("err-msg").classList.add("show");v=false}if(v){document.getElementById("successMsg").classList.add("show")}}</script></body></html>
"@

Write-Template 'minimalist-portfolio' 'Minimalist Coder Portfolio' 'Clean developer portfolio with dark/light toggle, filterable project grid, animated skill bars, and smooth sections.' 'Portfolios' 634 'MinimalDev' '18.7k' '1 week ago' @"
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Portfolio</title><style>:root{--bg:#f8fafc;--card:#fff;--text:#1e293b;--muted:#64748b;--border:#e2e8f0;--accent:#3b82f6;--accent2:#10b981}[data-theme=dark]{--bg:#0f172a;--card:#1e293b;--text:#e2e8f0;--muted:#94a3b8;--border:#334155;--accent:#60a5fa;--accent2:#34d399}*{margin:0;padding:0;box-sizing:border-box;font-family:system-ui,sans-serif;transition:background .3s,color .3s,border-color .3s}body{background:var(--bg);color:var(--text)}nav{position:fixed;top:0;width:100%;background:var(--bg);border-bottom:1px solid var(--border);z-index:100}.nav-inner{max-width:900px;margin:0 auto;display:flex;justify-content:space-between;align-items:center;padding:14px 24px}nav .logo{font-weight:700;font-size:1.1rem}nav ul{display:flex;gap:16px;list-style:none}nav ul a{color:var(--muted);text-decoration:none;font-size:.85rem}nav ul a:hover{color:var(--accent)}.theme-btn{background:0 0;border:1px solid var(--border);border-radius:8px;padding:6px 12px;cursor:pointer;color:var(--text);font-size:.8rem}section{max-width:900px;margin:0 auto;padding:80px 24px 40px}.hero{padding-top:120px;text-align:center}.hero h1{font-size:2.5rem;margin-bottom:8px}.hero h1 span{background:linear-gradient(135deg,var(--accent),var(--accent2));-webkit-background-clip:text;-webkit-text-fill-color:transparent}.hero p{color:var(--muted);margin-bottom:24px;font-size:1rem}.hero .socials{display:flex;gap:12px;justify-content:center}.hero .socials a{color:var(--muted);text-decoration:none;padding:8px 16px;border:1px solid var(--border);border-radius:8px;font-size:.85rem}.hero .socials a:hover{border-color:var(--accent);color:var(--accent)}h2{font-size:1.3rem;margin-bottom:24px}.filters{display:flex;gap:8px;margin-bottom:20px;flex-wrap:wrap}.filters button{padding:6px 14px;border:1px solid var(--border);border-radius:8px;background:0 0;color:var(--muted);cursor:pointer;font-size:.8rem}.filters button.active,.filters button:hover{border-color:var(--accent);color:var(--accent)}.p-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.project{background:var(--card);border:1px solid var(--border);border-radius:10px;padding:20px}.project h3{font-size:1rem;margin-bottom:8px}.project p{font-size:.8rem;color:var(--muted);margin-bottom:12px}.project .tags{display:flex;gap:6px;flex-wrap:wrap}.project .tags span{padding:2px 8px;border-radius:4px;background:var(--accent)15;color:var(--accent);font-size:.7rem}.skills{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.skill{margin-bottom:12px}.skill .lbl{display:flex;justify-content:space-between;font-size:.8rem;margin-bottom:4px}.skill .track{height:8px;background:var(--border);border-radius:4px;overflow:hidden}.skill .fill{height:100%;background:linear-gradient(90deg,var(--accent),var(--accent2));border-radius:4px;width:0;transition:width 1.5s}@media(max-width:600px){.p-grid,.skills{grid-template-columns:1fr}}</style></head><body><nav><div class="nav-inner"><span class="logo">dev</span><ul><li><a href="#work">Work</a></li><li><a href="#skills">Skills</a></li><li><a href="#contact">Contact</a></li></ul><button class="theme-btn" id="themeBtn" onclick="toggleTheme()">Dark</button></div></nav><section class="hero"><h1>Hi, I am <span>Alex Rivera</span></h1><p>Full-stack developer crafting performant web experiences.</p><div class="socials"><a href="#">GitHub</a><a href="#">LinkedIn</a><a href="#">Twitter</a></div></section><section id="work"><h2>Selected Projects</h2><div class="filters"><button class="active" onclick="filterP(&#39;all&#39;,this)">All</button><button onclick="filterP(&#39;react&#39;,this)">React</button><button onclick="filterP(&#39;python&#39;,this)">Python</button></div><div class="p-grid" id="pGrid"></div></section><section id="skills"><h2>Skills</h2><div class="skills" id="skillsGrid"></div></section><section id="contact"><h2>Contact</h2><p style="color:var(--muted)">alex@devmail.com</p></section><script>var projs=[{title:"FlowBoard",desc:"Kanban with real-time sync",tags:["React","Node.js"],cat:"react"},{title:"SentinelAuth",desc:"OAuth library with RBAC",tags:["Python","FastAPI"],cat:"python"},{title:"MeshUI",desc:"Design system with 60+ components",tags:["React","Storybook"],cat:"react"},{title:"DataForge",desc:"ETL pipeline with visual builder",tags:["Python","React"],cat:"python"},{title:"Gradiently",desc:"AI gradient generator",tags:["React","Canvas"],cat:"react"},{title:"SyncStack",desc:"CLI for multi-service orchestration",tags:["Go","Docker"],cat:"python"}];var sk=[{n:"React",l:92},{n:"TypeScript",l:88},{n:"Python",l:85},{n:"Node.js",l:90}];function renderP(l){document.getElementById("pGrid").innerHTML=l.map(function(p){return"<div class=\"project\"><h3>"+p.title+"</h3><p>"+p.desc+'</p><div class="tags">'+p.tags.map(function(t){return"<span>"+t+"</span>"}).join("")+"</div></div>"}).join("")}renderP(projs);window.filterP=function(c,b){document.querySelectorAll(".filters button").forEach(function(x){x.classList.remove("active")});b.classList.add("active");renderP(c==="all"?projs:projs.filter(function(p){return p.cat===c}))};document.getElementById("skillsGrid").innerHTML=sk.map(function(s){return"<div class=\"skill\"><div class=\"lbl\"><span>"+s.n+"</span><span>"+s.l+'%</span></div><div class=\"track\"><div class="fill" data-l="'+s.l+'"></div></div></div>'}).join("");setTimeout(function(){document.querySelectorAll(".fill").forEach(function(e){e.style.width=e.dataset.l+"%"})},500);window.toggleTheme=function(){var h=document.documentElement,b=document.getElementById("themeBtn");if(h.getAttribute("data-theme")==="dark"){h.removeAttribute("data-theme");b.textContent="Dark"}else{h.setAttribute("data-theme","dark");b.textContent="Light"}}</script></body></html>
"@

Write-Template 'saas-billing' 'SaaS Billing Dashboard' 'Interactive billing dashboard with monthly/yearly pricing toggle, live subscription history table, and payment method management.' 'SaaS' 521 'SaaSStack' '11.4k' '2 days ago' @"
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SaaS Billing</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:system-ui,sans-serif}body{background:#0f172a;color:#e2e8f0}.wrap{max-width:1000px;margin:0 auto;padding:32px 24px}h1{font-size:1.5rem;margin-bottom:4px}.sub{color:#94a3b8;font-size:.85rem;margin-bottom:24px}.tr{display:flex;align-items:center;gap:12px;justify-content:center;margin-bottom:32px}.tr span{font-size:.9rem;color:#94a3b8;cursor:pointer}.tr span.active{color:#e2e8f0;font-weight:600}.tog{width:48px;height:26px;background:#334155;border-radius:13px;cursor:pointer;position:relative}.tog.active{background:#6366f1}.tog .k{width:20px;height:20px;background:#fff;border-radius:50%;position:absolute;top:3px;left:3px;transition:transform .3s}.tog.active .k{transform:translateX(22px)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:32px}.plan{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:24px;text-align:center}.plan.feat{border-color:#6366f1;transform:scale(1.03)}.plan .nm{font-size:.8rem;text-transform:uppercase;color:#94a3b8;letter-spacing:1px;margin-bottom:8px}.plan .pr{font-size:2.5rem;font-weight:700}.plan .pr span{font-size:.9rem;color:#94a3b8;font-weight:400}.plan ul{list-style:none;margin:20px 0;text-align:left}.plan ul li{padding:6px 0;font-size:.85rem;color:#94a3b8}.plan ul li:before{content:">";color:#10b981;margin-right:8px}.plan .btn{display:block;padding:10px;border-radius:8px;text-align:center;font-weight:600;font-size:.85rem;text-decoration:none;border:1px solid #334155;color:#e2e8f0;margin-top:16px;cursor:pointer}.plan.feat .btn{background:#6366f1;color:#fff;border-color:#6366f1}table{width:100%;border-collapse:collapse;font-size:.85rem;margin-top:16px}th,td{padding:10px 8px;text-align:left;border-bottom:1px solid #334155}th{color:#94a3b8}.badge{padding:2px 10px;border-radius:99px;font-size:.75rem}.badge.active{background:#10b98120;color:#10b981}.badge.cancel{background:#ef444420;color:#ef4444}.badge.trial{background:#f59e0b20;color:#f59e0b}@media(max-width:700px){.cards{grid-template-columns:1fr}.plan.feat{transform:none}}</style></head><body><div class="wrap"><h1>Billing</h1><p class="sub">Manage subscription</p><div class="tr"><span id="moL" class="active">Monthly</span><div class="tog" id="tog" onclick="tog()"><div class="k"></div></div><span id="yrL">Yearly (Save 20%)</span></div><div class="cards" id="cards"></div><h2>History</h2><table><thead><tr><th>Plan</th><th>Status</th><th>Amount</th><th>Date</th></tr></thead><tbody id="hist"></tbody></table></div><script>var plans=[{n:"Starter",mo:19,yr:190,feat:false,fs:["5 Projects","10GB Storage","Basic Support"]},{n:"Professional",mo:49,yr:490,feat:true,fs:["Unlimited Projects","100GB Storage","Priority Support","Analytics"]},{n:"Enterprise",mo:149,yr:1490,feat:false,fs:["Unlimited Everything","Custom Integrations","SLA Guarantee"]}];var hist=[{p:"Professional",s:"active",a:49,d:"May 1, 2026"},{p:"Professional",s:"active",a:49,d:"Apr 1, 2026"},{p:"Starter",s:"cancel",a:19,d:"Mar 1, 2026"}];var yr=false;function rP(){document.getElementById("cards").innerHTML=plans.map(function(x){return'<div class="plan'+(x.feat?" feat":"")+'"><div class="nm">'+x.n+'</div><div class="pr">$'+(yr?x.yr:x.mo)+"<span>/"+(yr?"yr":"mo")+'</span></div><ul>'+x.fs.map(function(f){return"<li>"+f+"</li>"}).join("")+'</ul><a href="#" class="btn">'+(x.feat?"Current":"Switch")+"</a></div>"}).join("")}function rH(){document.getElementById("hist").innerHTML=hist.map(function(h){return"<tr><td>"+h.p+'</td><td><span class="badge '+h.s+'">'+h.s+"</span></td><td>$"+h.a+"</td><td>"+h.d+"</td></tr>"}).join("")}window.tog=function(){yr=!yr;document.getElementById("tog").classList.toggle("active");document.getElementById("moL").classList.toggle("active");document.getElementById("yrL").classList.toggle("active");rP()};rP();rH()</script></body></html>
"@

Write-Template 'analytics-dashboard' 'Analytics Hub Pro' 'Live analytics dashboard with canvas bar/line charts, date range filter, animated stat counters, and real-time data simulation.' 'Dashboards' 445 'DataVizPro' '8.9k' '4 days ago' @"
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Analytics Hub</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:system-ui,sans-serif}body{background:#0f172a;color:#e2e8f0}.w{max-width:1100px;margin:0 auto;padding:24px}.hd{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.hd h1{font-size:1.25rem}.hd select{padding:6px 12px;background:#1e293b;border:1px solid #334155;border-radius:6px;color:#e2e8f0;font-size:.8rem;outline:0}.st{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px}.s{background:#1e293b;border:1px solid #334155;border-radius:10px;padding:16px}.s .l{font-size:.7rem;color:#64748b;text-transform:uppercase}.s .v{font-size:1.5rem;font-weight:700;margin-top:4px}.s .c{font-size:.75rem}.s .c.u{color:#10b981}.s .c.d{color:#ef4444}.cr{display:grid;grid-template-columns:2fr 1fr;gap:16px;margin-bottom:20px}.cb{background:#1e293b;border:1px solid #334155;border-radius:10px;padding:16px}.cb h3{color:#94a3b8;font-size:.75rem;margin-bottom:12px}canvas{width:100%!important;height:200px!important}@media(max-width:700px){.st,.cr{grid-template-columns:1fr}}</style></head><body><div class="w"><div class="hd"><h1>Analytics Hub</h1><select onchange="alert(&#39;Range updated!&#39;)"><option selected>Last 30 days</option><option>Last 7 days</option><option>Last 90 days</option></select></div><div class="st"><div class="s"><div class="l">Visitors</div><div class="v" id="v1">0</div><div class="c u">+12.4%</div></div><div class="s"><div class="l">Page Views</div><div class="v" id="v2">0</div><div class="c u">+8.7%</div></div><div class="s"><div class="l">Bounce Rate</div><div class="v" id="v3">0%</div><div class="c d">-2.1%</div></div><div class="s"><div class="l">Avg Session</div><div class="v" id="v4">0s</div><div class="c u">+5.3%</div></div></div><div class="cr"><div class="cb"><h3>Page Views</h3><canvas id="chart"></canvas></div><div class="cb"><h3>Sources</h3><div id="srcs"></div></div></div></div><script>var srcs=[{n:"Google",p:42},{n:"Direct",p:28},{n:"Twitter",p:15},{n:"GitHub",p:10},{n:"Other",p:5}];var vd=[4200,5800,4900,7200,8100,6500,9400,10200,8800,11500,9800,12800,11200,13800,12400,15200,14500,16800,15200,18200,17200,19600,18500,21000,19800,22400,21500,23800,22500,24500];function drw(id,data,col){var c=document.getElementById(id);if(!c)return;var ctx=c.getContext("2d"),dpr=window.devicePixelRatio||1,r=c.parentElement.getBoundingClientRect();c.width=r.width*dpr;c.height=200*dpr;c.style.width=r.width+"px";c.style.height="200px";ctx.scale(dpr,dpr);var w=r.width,h=200,cw=w-40,ch=h-20,mx=Math.max.apply(null,data),grd=ctx.createLinearGradient(0,10,0,180);grd.addColorStop(0,col+"60");grd.addColorStop(1,col+"00");ctx.beginPath();data.forEach(function(v,i){var x=20+i/(data.length-1)*cw,y=10+ch-v/mx*ch;i===0?ctx.moveTo(x,y):ctx.lineTo(x,y)});data.forEach(function(v,i){ctx.lineTo(20+i/(data.length-1)*cw,10+ch)});ctx.closePath();ctx.fillStyle=grd;ctx.fill();ctx.beginPath();data.forEach(function(v,i){var x=20+i/(data.length-1)*cw,y=10+ch-v/mx*ch;i===0?ctx.moveTo(x,y):ctx.lineTo(x,y)});ctx.strokeStyle=col;ctx.lineWidth=2;ctx.stroke()}function anim(id,t){var e=document.getElementById(id),c=0,inc=t/75,ti=setInterval(function(){c+=inc;if(c>=t){c=t;clearInterval(ti)}if(id==="v3")e.textContent=c.toFixed(1)+"%";else if(id==="v4")e.textContent=Math.floor(c)+"s";else e.textContent=Math.floor(c).toLocaleString()},16)}anim("v1",28450);anim("v2",142800);anim("v3",32.4);anim("v4",247);drw("chart",vd,"#8b5cf6");document.getElementById("srcs").innerHTML=srcs.map(function(s){return'<div style="display:flex;justify-content:space-between;padding:6px 0;font-size:.85rem;border-bottom:1px solid #334155"><span style="color:#94a3b8">'+s.n+'</span><span>'+s.p+'%</span></div><div style="height:4px;background:#334155;border-radius:2px;margin-bottom:8px"><div style="height:100%;width:'+s.p+'%;background:#6366f1;border-radius:2px"></div></div>'}).join("")</script></body></html>
"@

Write-Template 'ecommerce-store' 'ShopGrid E-Commerce Store' 'Full online store with working cart (localStorage), product filter/search/sort, cart badge counter, and checkout flow with order confirmation.' 'E-Commerce' 678 'ShopDev' '15.6k' '6 days ago' @"
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ShopGrid</title><style>*{margin:0;padding:0;box-sizing:border-box;font-family:system-ui,sans-serif}body{background:#0f172a;color:#e2e8f0}.w{max-width:1100px;margin:0 auto;padding:24px}nav{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}nav h1{color:#f59e0b}.cart-btn{background:#1e293b;border:1px solid #334155;border-radius:8px;padding:8px 16px;cursor:pointer;color:#e2e8f0;position:relative}.cart-btn .b{position:absolute;top:-6px;right:-6px;background:#f59e0b;color:#0f172a;border-radius:50%;width:20px;height:20px;font-size:.7rem;display:flex;align-items:center;justify-content:center}.ctrls{display:flex;gap:12px;margin-bottom:20px;flex-wrap:wrap}.ctrls input,.ctrls select{padding:8px 12px;background:#1e293b;border:1px solid #334155;border-radius:6px;color:#e2e8f0;font-size:.8rem;outline:0}.ctrls input{flex:1;min-width:180px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:16px}.p{background:#1e293b;border:1px solid #334155;border-radius:10px;padding:16px}.p .img{height:140px;background:linear-gradient(135deg,#1e293b,#334155);border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:2.5rem;margin-bottom:12px}.p h3{font-size:.9rem;margin-bottom:4px}.p .pr{color:#f59e0b;font-weight:700;font-size:1.1rem}.p .pr s{color:#64748b;font-size:.75rem;margin-left:6px}.p .btn{width:100%;padding:8px;border-radius:6px;border:0;cursor:pointer;font-weight:600;font-size:.8rem;background:#f59e0b;color:#0f172a}.p .btn.in{background:#10b981}.ov{display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:#00000060;z-index:200}.ov.s{display:block}.md{display:none;position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#1e293b;border:1px solid #334155;border-radius:12px;padding:24px;width:90%;max-width:400px;z-index:201}.md.s{display:block}.md .item{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #334155;font-size:.85rem}.md .item .rm{color:#ef4444;cursor:pointer}.md .total{display:flex;justify-content:space-between;font-weight:700;margin-top:16px}</style></head><body><div class="w"><nav><h1>ShopGrid</h1><button class="cart-btn" onclick="togCart()">Cart <span class="b" id="cb">0</span></button></nav><div class="ctrls"><input id="sIn" placeholder="Search..." oninput="filt()"><select id="cFil" onchange="filt()"><option value="all">All</option><option value="el">Electronics</option><option value="cl">Clothing</option><option value="ac">Accessories</option></select><select id="sFil" onchange="filt()"><option value="name">Name</option><option value="asc">Price Low</option><option value="desc">Price High</option></select></div><div class="grid" id="pGrid"></div></div><div class="ov" id="ov" onclick="togCart()"></div><div class="md" id="md"><h2>Cart</h2><div id="cItems"></div><div class="total"><span>Total</span><span id="cTotal">$0</span></div><button style="width:100%;padding:10px;background:#f59e0b;color:#0f172a;border:0;border-radius:8px;font-weight:700;cursor:pointer;margin-top:16px" onclick="check()">Checkout</button></div><script>var prods=[{id:1,n:"Headphones",p:79.99,o:99.99,c:"el",e:"H"},{id:2,n:"Watch",p:199.99,o:249.99,c:"el",e:"W"},{id:3,n:"T-Shirt",p:24.99,o:34.99,c:"cl",e:"T"},{id:4,n:"Jacket",p:89.99,o:119.99,c:"cl",e:"J"},{id:5,n:"Wallet",p:39.99,o:49.99,c:"ac",e:"W"},{id:6,n:"Sunglasses",p:59.99,o:79.99,c:"ac",e:"S"},{id:7,n:"Speaker",p:49.99,o:69.99,c:"el",e:"S"},{id:8,n:"Shoes",p:129.99,o:159.99,c:"cl",e:"S"}];var cart=JSON.parse(localStorage.getItem("sc")||"[]");function sv(){localStorage.setItem("sc",JSON.stringify(cart));upd()}function upd(){document.getElementById("cb").textContent=cart.reduce(function(s,i){return s+i.q},0);if(!cart.length){document.getElementById("cItems").innerHTML="<p style=\"color:#94a3b8;text-align:center\">Empty</p>";document.getElementById("cTotal").textContent="$0";return}document.getElementById("cItems").innerHTML=cart.map(function(it,i){return"<div class=\"item\"><span>"+it.e+" "+it.n+" x"+it.q+'</span><span>$'+(it.p*it.q).toFixed(2)+' <span class="rm" onclick="rm('+i+')">X</span></span></div>'}).join("");document.getElementById("cTotal").textContent="$"+cart.reduce(function(s,i){return s+i.p*i.q},0).toFixed(2)}function rend(l){var g=document.getElementById("pGrid");if(!l.length){g.innerHTML="<p style=\"color:#94a3b8;text-align:center;padding:40px\">No products</p>";return}g.innerHTML=l.map(function(p){var ic=cart.find(function(i){return i.id===p.id});return'<div class="p"><div class="img">'+p.e+'</div><h3>'+p.n+'</h3><div class="pr">$'+p.p.toFixed(2)+' <s>$'+p.o.toFixed(2)+'</s></div><button class="btn'+(ic?" in":"")+'" onclick="add('+p.id+',\''+p.n+"',"+p.p+",'"+p.e+'\')">'+(ic?"Added":"Add")+"</button></div>"}).join("")}window.add=function(id,n,p,e){var ex=cart.find(function(i){return i.id===id});if(ex)ex.q++;else cart.push({id,n,p,e,q:1});sv();filt()};window.rm=function(i){cart.splice(i,1);sv()};window.togCart=function(){document.getElementById("ov").classList.toggle("s");document.getElementById("md").classList.toggle("s")};window.check=function(){if(!cart.length){alert("Cart empty!");return}alert("Order placed! Total: $"+cart.reduce(function(s,i){return s+i.p*i.q},0).toFixed(2));cart=[];sv();togCart();filt()};window.filt=function(){var list=[].concat(prods),q=document.getElementById("sIn").value.toLowerCase(),c=document.getElementById("cFil").value,s=document.getElementById("sFil").value;if(q)list=list.filter(function(p){return p.n.toLowerCase().includes(q)});if(c!=="all")list=list.filter(function(p){return p.c===c});if(s==="asc")list.sort(function(a,b){return a.p-b.p});else if(s==="desc")list.sort(function(a,b){return b.p-a.p});else list.sort(function(a,b){return a.n.localeCompare(b.n)});rend(list)};upd();filt()</script></body></html>
"@

